#define N 512
int matrix[N][N];

// SPATIAL LOCALITY: Array Traversal (C is Row-Major)
// Optimized performance requires accessing elements sequentially in memory.

// High Locality (Inner loop iterates over J index)
// M[i][0], M[i][1], M[i][2]...
for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
        matrix[i][j] = 1;
    }
}

// Low Locality (Inner loop iterates over I index)
// Forces large memory jumps, causing severe cache misses.
